import RNA, random, sys, time
from multiprocessing import Pool

t='((...((....((.....((.........((..............................))...............)).........)).......))....))....'
n=len(t)
st=[]; pairs={}
for i,c in enumerate(t):
    if c=='(': st.append(i)
    elif c==')': pairs[st.pop()]=i
pairpos=set(list(pairs.keys())+list(pairs.values()))

def sc(s):
    fc=RNA.fold_compound(s); m,_=fc.mfe(); return RNA.bp_distance(m,t)

def run(seed):
    random.seed(seed)
    seq=['A']*n
    for i in sorted(pairs):
        seq[i]='G'; seq[pairs[i]]='C'
    # randomize loops a bit
    for i in range(n):
        if i not in pairpos and random.random()<0.5:
            seq[i]=random.choice('ACGU')
    cur=''.join(seq)
    curd=sc(cur)
    best=cur[:]; bestd=curd
    t0=time.time()
    it=0
    while time.time()-t0<240:
        it+=1
        i=random.randrange(n)
        old=cur[i]
        nb=random.choice('ACGU')
        cur=cur[:i]+nb+cur[i+1:]
        nd=sc(cur)
        if nd<=curd:
            curd=nd
            if nd<bestd:
                bestd=nd; best=cur[:]
        else:
            # revert
            cur=cur[:i]+old+cur[i+1:]
        if bestd==0:
            break
    return seed,bestd,best,it

if __name__=='__main__':
    seeds=[int(x) for x in sys.argv[1:]]
    with Pool(len(seeds)) as p:
        for r in p.imap_unordered(run, seeds):
            print(r, flush=True)

